<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\StaffRole; use App\Models\User; use App\Services\AuditService; use App\Services\AccountPasswordService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class StaffRoleController extends Controller {
 public function index(){return view('admin.operations.roles', ['roles'=>StaffRole::with('permissions')->latest()->get(),'catalog'=>config('permissions.catalog')]);}
 public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:120','description'=>'nullable|string|max:1000','permissions'=>'array','permissions.*'=>'string','scope'=>'nullable|array']); return DB::transaction(function()use($d){$role=StaffRole::create(['name'=>$d['name'],'description'=>$d['description']??null]); foreach(array_unique($d['permissions']??[]) as $p)$role->permissions()->create(['permission'=>$p,'scope'=>$d['scope']??null]); AuditService::record('created','staff_roles',$role); return back()->with('success','تم إنشاء الدور.');});}
 public function update(Request $r, StaffRole $staffRole){$d=$r->validate(['name'=>'required|string|max:120','description'=>'nullable|string|max:1000','permissions'=>'array','permissions.*'=>'string','scope'=>'nullable|array']); DB::transaction(function()use($d,$staffRole){$staffRole->update(['name'=>$d['name'],'description'=>$d['description']??null]);$staffRole->permissions()->delete();foreach(array_unique($d['permissions']??[]) as $p)$staffRole->permissions()->create(['permission'=>$p,'scope'=>$d['scope']??null]);AuditService::record('updated','staff_roles',$staffRole);}); return back()->with('success','تم تحديث الدور.');}
 public function assign(Request $r, User $user){abort_if($user->is($r->user()),422,'لا يمكنك تعديل صلاحيات حسابك.');$d=$r->validate(['role_ids'=>'array','role_ids.*'=>'integer|exists:staff_roles,id','scope'=>'nullable|array']);$user->staffRoles()->sync(collect($d['role_ids']??[])->mapWithKeys(fn($id)=>[$id=>['scope'=>$d['scope']??null,'active'=>true]])->all());AuditService::record('updated','staff_role_assignments',$user);return back()->with('success','تم تحديث صلاحيات الموظف.');}
 public function storeStaff(Request $r, AccountPasswordService $passwords){$d=$r->validate(['name'=>'required|string|max:255','email'=>'required|email|unique:users,email','phone'=>'nullable|string|max:30','password'=>'nullable|string|min:8|confirmed','role_ids'=>'required|array|min:1','role_ids.*'=>'integer|exists:staff_roles,id','classroom_ids'=>'nullable|array','classroom_ids.*'=>'integer|exists:classrooms,id']);return DB::transaction(function()use($d,$passwords){$u=User::create(['name'=>$d['name'],'email'=>$d['email'],'phone'=>$d['phone']??null,'password'=>$passwords->forNewAccount($d['password']??null),'role'=>'staff','status'=>'active']);$u->staffRoles()->sync(collect($d['role_ids'])->mapWithKeys(fn($id)=>[$id=>['scope'=>json_encode(['classroom_ids'=>$d['classroom_ids']??[]]),'active'=>true]])->all());AuditService::record('created','staff_users',$u);return back()->with('success','تم إنشاء حساب الموظف وربط صلاحياته.');});}
}
